def plus_cover(c, r):
    x,y=c; out=set()
    for k in range(-13,14): out.add((x+k,y)); out.add((x,y+k))
    return out
def xcover(c, r):
    x,y=c; out=set()
    for k in range(-11,12):
        out|={(x+k,y+k),(x+k,y-k)}
    return out
def diamond_cover(c, r):
    x,y=c
    return {(x+dr,y+dc) for dr in range(-9,10) for dc in range(-9,10) if abs(dr)+abs(dc)==9}
def route(start, end, order):
    x,y=start; pts=[(x,y)]
    moves = [('row',end[0]) if order=='row' else ('col',end[1])]
    if order=='row': moves=[('row',end[0]),('col',end[1])]
    else: moves=[('col',end[1]),('row',end[0])]
    for axis,tgt in moves:
        while (x if axis=='row' else y) != tgt:
            if axis=='row': x += 3 if tgt>x else -3
            else: y += 3 if tgt>y else -3
            pts.append((x,y))
    return pts
